M="pharm-micro"
SUB="Antimicrobials"
BOSS=dict(th="เคสใหญ่: ไข้ คอแข็ง",en="Boss case: Fever and a stiff neck",
case="A 20-year-old university student has 12 hours of fever, severe headache, neck stiffness and a petechial rash on the legs. CSF: neutrophils, low glucose, high protein; Gram stain shows gram-negative diplococci.",
qs=[
("Most likely organism:",["Neisseria meningitidis","Streptococcus pneumoniae","Listeria monocytogenes","Haemophilus influenzae"],0,"Petechial rash and gram-negative diplococci."),
("Empiric therapy for bacterial meningitis in a young adult:",["Ceftriaxone + vancomycin","Oral amoxicillin alone","Gentamicin + clindamycin","Azithromycin + doxycycline"],0,"± dexamethasone. Add ampicillin for Listeria if > 50 years or immunocompromised."),
("Ceftriaxone works by:",["Inhibiting peptidoglycan cross-linking","Binding the 30S ribosomal subunit (A site)","Inhibiting DNA gyrase and topo IV","Inhibiting dihydropteroate synthase"],0,"Binds PBPs; β-lactam; bactericidal."),
("Close contacts should receive prophylaxis with:",["Rifampin or ciprofloxacin","Vancomycin or linezolid","Metronidazole or clindamycin","Amoxicillin or cephalexin"],0,"Single-dose ciprofloxacin or IM ceftriaxone is also used."),
("Vancomycin is added mainly to cover:",["Resistant S. pneumoniae","Listeria monocytogenes","Pseudomonas aeruginosa","Bacteroides fragilis"],0,"Penicillin/cephalosporin-resistant pneumococci; altered PBPs confer resistance."),
("A vancomycin infusion reaction (diffuse flushing) is prevented by:",["Slower infusion and antihistamines","Co-administering probenecid","Adding gentamicin to each dose","Premedication with epinephrine and fluids"],0,"Non-IgE histamine release, not an allergy."),
],pass_=4)
T={
"bactmap":[("Which class inhibits the 30S ribosomal subunit?",["Aminoglycosides and tetracyclines","Macrolides and clindamycin","Oxazolidinones and chloramphenicol","Lincosamides and streptogramins"],0,"Buy AT 30, CCEL at 50."),
 ("Fluoroquinolones inhibit:",["DNA gyrase and topoisomerase IV","Cell wall transpeptidases (PBPs)","DNA-dependent RNA polymerase","Bacterial dihydrofolate reductase"],0,"Rifampin inhibits RNA polymerase."),
 ('A 21-year-old student has 2 weeks of low-grade fever, dry cough and malaise; chest X-ray shows patchy interstitial infiltrates and cold agglutinin titers are elevated. The causative organism has no cell wall. Which antibiotic class would be ineffective?', ['β-lactams (e.g., amoxicillin)', 'Macrolides (e.g., azithromycin)', 'Tetracyclines (e.g., doxycycline)', 'Fluoroquinolones (e.g., levofloxacin)'], 0, 'Mycoplasma pneumoniae lacks peptidoglycan, so cell-wall inhibitors have no target. Ribosomal (macrolide, tetracycline) and gyrase inhibitors remain active.', 3)],
"penicillin":[("β-lactamase inhibitors include:",["Clavulanate, sulbactam, tazobactam","Aztreonam, imipenem, cefepime","Vancomycin, daptomycin, telavancin","Probenecid, cilastatin, allopurinol"],0,"Combined with amoxicillin, ampicillin, piperacillin."),
 ("Penicillinase-resistant penicillins (nafcillin, dicloxacillin) are used for:",["MSSA","MRSA","Pseudomonas","Enterococcus"],0,"Bulky side chain blocks β-lactamase."),
 ('A 24-year-old man has a painless, indurated genital ulcer with a clean base and nontender inguinal lymphadenopathy for 1 week. Dark-field microscopy of the ulcer exudate shows motile spirochetes. Most appropriate treatment?', ['Benzathine penicillin G, single IM dose', 'Ciprofloxacin, oral, for 3 days', 'Metronidazole, oral, single 2-g dose', 'Acyclovir, oral, for 7–10 days'], 0, 'Primary syphilis (Treponema pallidum) is treated with IM benzathine penicillin G. Acyclovir treats HSV, whose ulcers are painful and vesicular.', 2)],
"ceph":[("Which cephalosporin covers MRSA?",["Ceftaroline","Ceftriaxone","Cefazolin","Cefepime"],0,"5th generation; binds PBP2a."),
 ("Aztreonam is safe in penicillin allergy because:",["It is a monobactam with no cross-reactivity","It lacks a β-lactam ring and cannot bind PBPs","It is a carbapenem, not a penicillin","It is given orally, avoiding sensitization"],0,"Covers gram-negative rods only."),
 ('A 62-year-old man on mechanical ventilation in the ICU develops fever and purulent sputum. Sputum culture grows an oxidase-positive, lactose-nonfermenting gram-negative rod with a grape-like odor. Which cephalosporin would cover this organism?', ['Cefepime', 'Cefazolin', 'Ceftriaxone', 'Cephalexin'], 0, 'Pseudomonas aeruginosa is covered by the 4th-generation cefepime (and ceftazidime). Ceftriaxone lacks reliable antipseudomonal activity.', 3)],
"vanco":[("Vancomycin binds:",["D-Ala-D-Ala of cell wall precursors","Penicillin-binding proteins (transpeptidases)","Aminoacyl-tRNA site on the 30S subunit","DNA gyrase (topoisomerase II)"],0,"Resistance: D-Ala-D-Lac (VRE)."),
 ("Daptomycin should not be used for:",["Community-acquired pneumonia","S. aureus bacteremia","Right-sided endocarditis","Complicated skin and soft-tissue infection"],0,"Inactivated by pulmonary surfactant. Monitor CK for myopathy."),
 ('A 66-year-old man on hemodialysis has fever; blood cultures grow catalase-negative gram-positive cocci that grow in 6.5% NaCl and hydrolyze bile esculin. The isolate is resistant to vancomycin. Mechanism of resistance?', ['Cell-wall D-Ala-D-Ala changed to D-Ala-D-Lac', 'Altered PBP2a with low β-lactam affinity', 'Plasmid-encoded β-lactamase production', 'Efflux pump that exports the drug'], 0, 'VRE (Enterococcus) replaces the terminal D-Ala-D-Ala with D-Ala-D-Lac, which vancomycin binds poorly. PBP2a (mecA) is the mechanism of MRSA.', 3)],
"aminogly":[("Aminoglycoside toxicities:",["Nephrotoxicity and ototoxicity","Hepatotoxicity and pancreatitis","Cardiotoxicity and QT prolongation","Photosensitivity and tooth staining"],0,"Also neuromuscular blockade; teratogenic."),
 ("Aminoglycosides are ineffective against anaerobes because:",["Uptake requires O₂-dependent transport","They are destroyed by anaerobes","They need low pH","They bind 50S"],0,"Synergy with β-lactams."),
 ('A 68-year-old man receiving IV ampicillin plus gentamicin for enterococcal endocarditis develops tinnitus and an unsteady gait, and his creatinine rises from 1.0 to 2.1 mg/dL. The drug responsible for these effects acts by:', ['Binding the 30S subunit, causing mRNA misreading', 'Binding the 50S subunit, blocking translocation', 'Inhibiting peptidoglycan transpeptidation', 'Inhibiting DNA gyrase and topoisomerase IV'], 0, 'Gentamicin (aminoglycoside) causes ototoxicity and nephrotoxicity; it binds the 30S subunit and blocks initiation/causes misreading. Ampicillin inhibits transpeptidation and lacks these toxicities.', 3)],
"tetra":[("Tetracyclines should not be taken with:",["Milk, antacids or iron supplements","Plain water while sitting upright","Vitamin C or orange juice","Acetaminophen or ibuprofen"],0,"Divalent/trivalent cations chelate the drug → ↓ absorption."),
 ("Tetracyclines are avoided in children because of:",["Tooth discoloration and impaired bone growth","Gray baby syndrome and circulatory collapse","Kernicterus from bilirubin displacement off albumin","Ototoxicity and vestibular damage"],0,"Also photosensitivity."),
 ('A 30-year-old man from Connecticut has an expanding erythematous annular rash with central clearing on his thigh 10 days after a hiking trip, with fever and myalgia. The drug of choice acts by:', ['Blocking aminoacyl-tRNA binding at the 30S A site', 'Blocking translocation at the 50S subunit', 'Inhibiting peptidoglycan transpeptidation', 'Inhibiting bacterial DNA-dependent RNA polymerase'], 0, 'Early Lyme disease (erythema migrans) is treated with doxycycline, a tetracycline that blocks tRNA attachment at the 30S A site. Macrolides block 50S translocation.', 3)],
"macro":[("Macrolides can cause:",["QT prolongation and ↑ GI motility","Red man syndrome with rapid infusion","Achilles tendon rupture in the elderly","Gray baby syndrome in neonates"],0,"Erythromycin inhibits CYP3A4."),
 ("Clindamycin is associated with:",["C. difficile colitis","Achilles tendon rupture","Hemolysis in G6PD deficiency","Irreversible ototoxicity"],0,"Good anaerobic coverage above the diaphragm."),
 ('A 4-year-old unvaccinated girl has 2 weeks of paroxysmal coughing spells ending in an inspiratory whoop and post-tussive vomiting. WBC is 32,000/mm³ with 75% lymphocytes. The drug of choice acts by:', ['Blocking translocation at the 50S subunit', 'Blocking aminoacyl-tRNA entry at the 30S', 'Inhibiting peptidoglycan transpeptidation', 'Inhibiting bacterial DNA gyrase'], 0, 'Pertussis is treated with azithromycin, a macrolide that binds 23S rRNA of the 50S subunit and blocks translocation. Tetracyclines act at the 30S A site.', 3)],
"linezolid":[("Linezolid adverse effects include:",["Myelosuppression and serotonin syndrome","Nephrotoxicity and ototoxicity","Tendon rupture and photosensitivity reactions","Gray baby syndrome and kernicterus"],0,"Weak MAO inhibition."),
 ("Chloramphenicol in neonates causes:",["Gray baby syndrome","Neonatal kernicterus","Permanent tooth staining","Neonatal Reye syndrome"],0,"Lack of UDP-glucuronosyltransferase."),
 ('A 58-year-old woman taking sertraline is started on an oral antibiotic for vancomycin-resistant Enterococcus faecium bacteremia. Two days later she has agitation, hyperthermia, diaphoresis and inducible clonus. How does the new antibiotic kill bacteria?', ['Blocks formation of the 50S initiation complex', 'Depolarizes the bacterial cell membrane', 'Binds D-Ala-D-Ala of cell-wall precursors', 'Blocks aminoacyl-tRNA entry at the 30S site'], 0, 'Linezolid (oral, VRE-active) is a weak MAO inhibitor that precipitates serotonin syndrome with SSRIs; it binds 23S rRNA and blocks the initiation complex. Daptomycin depolarizes membranes but is IV-only and not serotonergic.', 3)],
"folate":[("Trimethoprim–sulfamethoxazole can cause:",["Hyperkalemia and G6PD hemolysis","Hypokalemia and ototoxicity","Red man syndrome and tendon rupture","Tooth staining and gray baby syndrome"],0,"Also SJS, and kernicterus in neonates."),
 ("Sulfonamides inhibit:",["Dihydropteroate synthase","Dihydrofolate reductase","Thymidylate synthase","DNA gyrase"],0,"Trimethoprim inhibits bacterial DHFR."),
 ('A 35-year-old man with HIV (CD4 120/mm³) takes TMP-SMX for Pneumocystis prophylaxis. Routine labs show K⁺ 6.1 mEq/L with normal renal function and no hemolysis. Mechanism of the hyperkalemia?', ['Trimethoprim blocks ENaC in the collecting duct', 'Sulfamethoxazole inhibits adrenal aldosterone synthesis', 'Trimethoprim directly inhibits Na⁺/K⁺-ATPase', 'Sulfamethoxazole causes intravascular cell lysis'], 0, 'Trimethoprim acts like amiloride, blocking the collecting-duct epithelial Na⁺ channel and reducing K⁺ secretion. It does not inhibit aldosterone synthesis.', 3)],
"fq":[("Fluoroquinolones are associated with:",["Tendon rupture and QT prolongation","Gray baby syndrome and kernicterus","Red man syndrome on rapid infusion","Permanent tooth discoloration"],0,"Avoid in pregnancy and children."),
 ("Metronidazole with alcohol can cause:",["Disulfiram-like reaction","Acute serotonin syndrome","Tyramine hypertensive crisis","Severe hypoglycemia"],0,"Covers anaerobes and protozoa."),
 ('A 72-year-old woman taking long-term prednisone for COPD is treated with levofloxacin for pneumonia. Five days later she feels a sudden pop in her posterior heel and cannot rise on her toes; squeezing the calf produces no plantar flexion. The antibiotic acts by:', ['Inhibiting DNA gyrase and topoisomerase IV', 'Inhibiting DNA-dependent RNA polymerase', 'Binding the 50S subunit, blocking translocation', 'Inhibiting bacterial dihydrofolate reductase'], 0, 'Fluoroquinolones cause tendinopathy/Achilles rupture (higher risk with age and corticosteroids) and inhibit DNA gyrase and topoisomerase IV. Rifampin inhibits RNA polymerase.', 3)],
"tb":[("Isoniazid adverse effects include:",["Peripheral neuropathy and hepatotoxicity","Red-orange body fluids and CYP induction","Hyperuricemia and arthralgia","Ototoxicity and nephrotoxicity"],0,"Give pyridoxine (B6). Ethambutol: optic neuritis; rifampin: orange fluids; pyrazinamide: hyperuricemia."),
 ("Rifampin is a potent:",["CYP450 inducer","CYP450 inhibitor","MAO inhibitor","DHFR inhibitor"],0,"Reduces efficacy of warfarin, contraceptives."),
 ('A 40-year-old man with cavitary pulmonary tuberculosis on four-drug therapy reports blurred vision; testing shows reduced acuity and red-green color blindness. The responsible drug acts by:', ['Inhibiting arabinosyltransferase', 'Inhibiting mycolic acid synthesis', 'Inhibiting DNA-dependent RNA polymerase', 'Conversion to pyrazinoic acid'], 0, 'Ethambutol causes optic neuritis and blocks arabinosyltransferase (arabinogalactan synthesis). Isoniazid inhibits mycolic acid synthesis and causes peripheral neuropathy.', 3)],
"prophylaxis":[("Pneumocystis prophylaxis in HIV begins at CD4 <:",["200 cells/mm³","500 cells/mm³","100 cells/mm³","50 cells/mm³"],0,"TMP-SMX."),
 ("Prophylaxis for MAC in HIV (when not on ART) at CD4 < 50:",["Azithromycin","TMP-SMX","Fluconazole","Ganciclovir"],0,"Not needed if ART started promptly."),
 ('A 32-year-old man is newly diagnosed with HIV. CD4 count is 80/mm³ and Toxoplasma IgG is positive. Which single drug provides the most appropriate primary prophylaxis?', ['Trimethoprim-sulfamethoxazole', 'Azithromycin (weekly dose)', 'Fluconazole (daily dose)', 'Dapsone alone (daily dose)'], 0, 'TMP-SMX covers both Pneumocystis (CD4 < 200) and Toxoplasma (CD4 < 100, IgG+). Dapsone alone covers Pneumocystis but not Toxoplasma.', 2)],
"fungmap":[("Amphotericin B binds:",["Ergosterol, forming membrane pores","Lanosterol 14α-demethylase (CYP51)","β-glucan synthase in the cell wall","Fungal microtubules (tubulin)"],0,"Nephrotoxic; hypokalemia and hypomagnesemia."),
 ("Echinocandins (caspofungin) inhibit:",["β-glucan synthesis","Ergosterol synthesis","Nucleic acid synthesis","Microtubules"],0,"Used for invasive Candida and Aspergillus."),
 ('A 65-year-old man with acute myeloid leukemia and prolonged neutropenia develops fever and hemoptysis; CT shows a nodule with a surrounding halo. Biopsy shows septate hyphae branching at acute angles. The drug of choice acts by:', ['Inhibiting lanosterol 14α-demethylase', 'Binding ergosterol to form membrane pores', 'Inhibiting β-glucan synthase', 'Inhibiting fungal microtubule function'], 0, 'Invasive aspergillosis is treated with voriconazole, an azole that blocks ergosterol synthesis at 14α-demethylase. Amphotericin B binds ergosterol and is a second-line alternative.', 3)],
"antiparasite":[("Ivermectin is used for:",["Strongyloides and onchocerciasis","Falciparum and vivax malaria","Toxoplasmosis and Pneumocystis pneumonia","Giardiasis and amebiasis"],0,"Glutamate-gated Cl⁻ channels in parasites."),
 ("Praziquantel treats:",["Schistosomes, tapeworms, flukes","Pinworms, hookworms, roundworms","Giardia, Entamoeba, Trichomonas","Plasmodium, Babesia, Toxoplasma"],0,"↑ Ca²⁺ permeability."),
 ('A 7-year-old girl has perianal itching that is worst at night. A cellophane tape test shows ova that are flattened on one side. She is treated with albendazole, which acts by:', ['Inhibiting helminth microtubule polymerization', 'Increasing helminth membrane Ca²⁺ permeability', 'Activating glutamate-gated Cl⁻ channels', 'Inhibiting parasite heme polymerase'], 0, "Enterobius vermicularis is treated with albendazole (or pyrantel); benzimidazoles bind β-tubulin. Increased Ca²⁺ permeability is praziquantel's mechanism.", 3)],
"malaria":[("Primaquine targets:",["Liver hypnozoites of P. vivax/ovale","Heme polymerase in the food vacuole","Parasite dihydrofolate reductase","The PfCRT chloroquine transporter"],0,"Check G6PD first (hemolysis)."),
 ("Severe falciparum malaria is treated with:",["IV artesunate","Chloroquine","Primaquine","Doxycycline alone"],0,"Artemisinins generate free radicals."),
 ('A 28-year-old man returns from India with fevers recurring every 48 hours. Blood smear shows enlarged red cells with Schüffner dots. He is treated with chloroquine. Before adding a drug to prevent relapse, which test is required?', ['G6PD enzyme activity', 'HLA-B*57:01 genotype', 'TPMT enzyme activity', 'Serum ferritin level'], 0, 'P. vivax forms liver hypnozoites, eradicated by primaquine (or tafenoquine), which causes hemolysis in G6PD deficiency. HLA-B*57:01 is screened before abacavir.', 3)],
"virmap":[("Acyclovir must be phosphorylated first by:",["Viral thymidine kinase","Host kinase only","Viral protease","Reverse transcriptase"],0,"Selective for infected cells; HSV/VZV."),
 ("Oseltamivir inhibits:",["Influenza neuraminidase","M2 ion channel","DNA polymerase","Reverse transcriptase"],0,"Decreases release of progeny virus."),
 ('A 38-year-old man with AIDS (CD4 30/mm³) has blurred vision; fundoscopy shows fluffy yellow-white retinal lesions with hemorrhages. He is started on IV ganciclovir. Activation of this drug first requires:', ['Phosphorylation by viral UL97 kinase', 'Phosphorylation by viral thymidine kinase', 'No activation; binds the pyrophosphate site', 'Cleavage by a viral protease'], 0, 'CMV retinitis: ganciclovir is monophosphorylated by the CMV UL97 kinase. Foscarnet needs no activation; HSV/VZV thymidine kinase activates acyclovir.', 3)],
"hiv":[("Abacavir requires screening for:",["HLA-B*57:01","HLA-B*58:01","HLA-B*15:02","TPMT"],0,"Hypersensitivity reaction."),
 ("Integrase inhibitors include:",["Dolutegravir, bictegravir, raltegravir","Efavirenz, rilpivirine, nevirapine","Darunavir, atazanavir, lopinavir, ritonavir","Maraviroc, enfuvirtide, ibalizumab"],0,"Core of most first-line regimens."),
 ('A 34-year-old man is started on tenofovir, emtricitabine and efavirenz. Two weeks later he reports vivid dreams, insomnia and dizziness. The responsible drug acts by:', ['Binding reverse transcriptase at an allosteric site', 'Competing with nucleotides at the RT active site', 'Blocking strand transfer by viral integrase', 'Inhibiting cleavage of the gag-pol polyprotein'], 0, 'Efavirenz (an NNRTI) causes CNS effects and binds RT away from the active site. Tenofovir and emtricitabine are NRTIs that compete at the active site.', 3)],
"hep":[("Sofosbuvir inhibits HCV:",["NS5B RNA polymerase","NS3/4A protease","NS5A","Reverse transcriptase"],0,"Pan-genotypic regimens cure > 95%."),
 ("Tenofovir and entecavir treat:",["Chronic hepatitis B","Hepatitis C only","Hepatitis A","Hepatitis E"],0,"Nucleos(t)ide analogs."),
 ('A 40-year-old man has been HBsAg-positive for over 6 months. He is HBeAg-positive, HBV DNA is 2 × 10⁷ IU/mL and ALT is 3 times the upper limit of normal. He is started on tenofovir, which acts by:', ['Inhibiting HBV polymerase (reverse transcriptase)', 'Inhibiting the viral NS5B RNA polymerase', 'Inhibiting the viral NS3/4A serine protease', 'Blocking viral entry via the NTCP receptor'], 0, "Chronic active hepatitis B is treated with tenofovir or entecavir, which inhibit the HBV polymerase's reverse transcriptase activity. NS5B and NS3/4A are hepatitis C targets.", 3)],
}
